"""Write the per-symbol data-window table into docs/02-domain/data-profile-v1.md (Sprint 04 audit).

Idempotent: the section between the markers is replaced. Usage: uv run python scripts/window_audit.py
"""

import re

import psycopg

from market_data import config
from market_data.read import list_instruments

START, END = "<!-- window-audit:start -->", "<!-- window-audit:end -->"


def build(rows: list[dict]) -> str:
    lines = [START, "## Bars per symbol (Sprint 04 audit)", "",
             "Generated by `scripts/window_audit.py` from `read.list_instruments` (stored bars, source alpaca).", "",
             "| Symbol | Type | Bars | First date | Last date |", "|---|---|---|---|---|"]
    for r in rows:
        lines.append(f"| {r['symbol']} | {r['asset_type']} | {r['bars']} | {r['first_date']} | {r['last_date']} |")
    big = sum(1 for r in rows if r["bars"] >= 1000)
    from collections import Counter
    modal = Counter(r["first_date"] for r in rows).most_common(1)[0][0]
    early = [r for r in rows if r["first_date"] < modal]
    lines += ["", f"**Contiguous window.** {len(rows) - len(early)} of {len(rows)} symbols start on {modal}. "
              + ("Earlier first dates: " + ", ".join(f"{r['symbol']} ({r['first_date']})" for r in early)
                 + "; check `bars` against the date range: these symbols hold only isolated early bars followed by a long "
                 "gap (verified on 2026-11-08: one stray bar each, then nothing until the common start). The usable, contiguous window of the whole universe therefore starts on "
                 f"{modal}, not in 2018." if early else "No symbol starts earlier.")]
    lines += ["", f"{len(rows)} symbols; {big} have at least 1,000 bars; the minimum is {min(r['bars'] for r in rows)} and the maximum "
              f"{max(r['bars'] for r in rows)}. Splits and walk-forward folds must fit inside these windows (ADR 0012).", END]
    return "\n".join(lines)


def main() -> None:
    path = config.DOCS_DIR / "02-domain" / "data-profile-v1.md"
    text = path.read_text(encoding="utf-8")
    with psycopg.connect(config.database_url()) as conn:
        block = build(list_instruments(conn))
    if START in text:
        text = re.sub(re.escape(START) + r".*?" + re.escape(END), lambda _: block, text, flags=re.S)
    else:
        text = text.rstrip("\n") + "\n\n" + block + "\n"
    path.write_text(text, encoding="utf-8")
    print(path)


if __name__ == "__main__":
    main()
